 egin{aligned}
\langle\mu,\muangle
&= rac1{\operatorname{St}_G(s)^2}
\sum_{\substack{T
i s\T'
i s}}
\sum_{\substack{	heta\in(T^F)^\vee\	heta'\in(T'^F)^\vee}}
	heta(s^{-1})	heta'(s)
\#\{n\in N(T,T')^F\mid \operatorname{ad}n(	heta')=	heta\}|T^F|^{-1}\
&= rac1{\operatorname{St}_G(s)^2}
\sum_{\substack{T
i s\	heta\in(T^F)^\vee\n\in G^F\nsn^{-1}\in T}}
	heta(s^{-1})	heta(nsn^{-1})|T^F|^{-1}\
&= rac1{\operatorname{St}_G(s)^2}
\#\{T
i s,\ n\in G^F\mid sn=ns\}\
&= rac{|Z(s)^F|}{\operatorname{St}_G(s)^2}
\#\{F	ext{-stable maximal tori in }Z^0(s)\}
=|Z(s)^F|
\end{aligned}

